mapper.select:
SELECT d.id, d.parent_id, d.ancestors, d.dept_name, d.order_num, d.leader, d.phone, d.email, d.status, d.del_flag, d.create_by, d.create_time, d.update_by, d.update_time, d.remark, pd.dept_name AS parent_name FROM sys_dept d LEFT JOIN sys_dept pd ON d.parent_id = pd.id AND pd.del_flag = 0 WHERE d.del_flag = 0
AND d.dept_name LIKE CONCAT('%', #{deptName}, '%')
AND d.status = #{status}
AND d.parent_id = #{parentId}
ORDER BY d.order_num ASC, d.create_time DESC
